import re
import pytest
from hypothesis import given, strategies as st

from roman import to_roman, from_roman


# ---------- obviously-correct reference model (derived from SPEC) ----------

_REF_TABLE = (
    (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
    (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
    (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
)
_REF_VALUES = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}


def ref_to_roman(n: int) -> str:
    out = []
    for value, numeral in _REF_TABLE:
        while n >= value:
            out.append(numeral)
            n -= value
    return "".join(out)


def ref_parse_loose(s: str) -> int:
    total = 0
    prev = 0
    for ch in reversed(s):
        v = _REF_VALUES[ch]
        if v < prev:
            total -= v
        else:
            total += v
            prev = v
    return total


def ref_from_roman(s: str) -> int:
    # strict: accept iff s == ref_to_roman(n) for some 1..3999
    if not isinstance(s, str):
        raise TypeError
    if s == "":
        raise ValueError
    for ch in s:
        if ch not in _REF_VALUES:
            raise ValueError(f"bad char {ch!r}")
    n = ref_parse_loose(s)
    if not 1 <= n <= 3999:
        raise ValueError
    if ref_to_roman(n) != s:
        raise ValueError
    return n


CANONICAL_RE = re.compile(
    r"^M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$"
)


# ---------- concrete examples from SPEC ----------

def test_example_to_roman_4():
    assert to_roman(4) == "IV"


def test_example_to_roman_1994():
    assert to_roman(1994) == "MCMXCIV"


def test_example_to_roman_3999():
    assert to_roman(3999) == "MMMCMXCIX"


def test_example_from_roman_lviii():
    assert from_roman("LVIII") == 58


def test_example_from_roman_iiii_rejected():
    with pytest.raises(ValueError):
        from_roman("IIII")


def test_example_to_roman_zero_rejected():
    with pytest.raises(ValueError):
        to_roman(0)


# ---------- equivalence to reference model ----------

@given(st.integers(min_value=1, max_value=3999))
def test_to_roman_matches_reference(n):
    assert to_roman(n) == ref_to_roman(n)


@given(st.integers(min_value=1, max_value=3999))
def test_from_roman_accepts_every_canonical_string(n):
    s = ref_to_roman(n)
    assert from_roman(s) == n


@given(st.integers(min_value=1, max_value=3999))
def test_roundtrip_from_to_roman_is_identity(n):
    assert from_roman(to_roman(n)) == n


@given(st.integers(min_value=1, max_value=3999))
def test_roundtrip_to_from_roman_is_identity(n):
    s = ref_to_roman(n)
    assert to_roman(from_roman(s)) == s


@given(st.integers(min_value=1, max_value=3999))
def test_to_roman_result_matches_canonical_grammar(n):
    s = to_roman(n)
    assert isinstance(s, str)
    assert s == s.upper()
    assert CANONICAL_RE.match(s) is not None
    # only allowed subtractive pairs appear
    for i, ch in enumerate(s):
        pass
    assert "IIII" not in s and "XXXX" not in s and "CCCC" not in s
    assert "VV" not in s and "LL" not in s and "DD" not in s
    assert "IC" not in s and "XM" not in s and "IL" not in s and "IM" not in s


@given(st.integers(min_value=1, max_value=3999))
def test_from_roman_result_is_int_in_range(n):
    s = ref_to_roman(n)
    v = from_roman(s)
    assert type(v) is int
    assert 1 <= v <= 3999


# ---------- repeated-symbol handling (greedy must repeat) ----------

@pytest.mark.parametrize("n, expected", [
    (1, "I"), (2, "II"), (3, "III"), (6, "VI"), (7, "VII"), (8, "VIII"),
    (13, "XIII"), (20, "XX"), (30, "XXX"), (200, "CC"), (300, "CCC"),
    (2000, "MM"), (3000, "MMM"), (1666, "MDCLXVI"), (3888, "MMMDCCCLXXXVIII"),
    (40, "XL"), (90, "XC"), (400, "CD"), (900, "CM"), (9, "IX"),
    (44, "XLIV"), (99, "XCIX"), (444, "CDXLIV"), (999, "CMXCIX"),
])
def test_to_roman_repeated_and_subtractive_cases(n, expected):
    assert to_roman(n) == expected


@pytest.mark.parametrize("s, expected", [
    ("I", 1), ("II", 2), ("III", 3), ("VI", 6), ("VIII", 8),
    ("XXX", 30), ("MMM", 3000), ("XL", 40), ("XC", 90),
    ("CD", 400), ("CM", 900), ("IX", 9), ("XLIV", 44),
    ("XCIX", 99), ("CDXLIV", 444), ("CMXCIX", 999),
    ("LVIII", 58), ("XIV", 14), ("MCMXCIV", 1994), ("MMMCMXCIX", 3999),
])
def test_from_roman_subtractive_values(s, expected):
    assert from_roman(s) == expected


# ---------- range / type errors for to_roman ----------

@pytest.mark.parametrize("n", [0, -1, -100, 4000, 4001, 10000, -3999])
def test_to_roman_out_of_range_raises_value_error(n):
    with pytest.raises(ValueError):
        to_roman(n)


@given(st.integers(min_value=4000, max_value=100000))
def test_to_roman_large_ints_raise_value_error(n):
    with pytest.raises(ValueError):
        to_roman(n)


@given(st.integers(min_value=-100000, max_value=0))
def test_to_roman_nonpositive_ints_raise_value_error(n):
    with pytest.raises(ValueError):
        to_roman(n)


@pytest.mark.parametrize("bad", [True, False, 1.0, 4.0, "IV", "1", None, [4], (4,), 4.5])
def test_to_roman_wrong_type_raises_type_error(bad):
    with pytest.raises(TypeError):
        to_roman(bad)


def test_to_roman_bool_is_type_error_not_value_error():
    # bool is subclass of int but SPEC demands TypeError
    with pytest.raises(TypeError):
        to_roman(True)
    with pytest.raises(TypeError):
        to_roman(False)


# ---------- type errors for from_roman ----------

@pytest.mark.parametrize("bad", [None, 123, 4.5, True, False, b"IV", ["X"], ("X",), 58])
def test_from_roman_wrong_type_raises_type_error(bad):
    with pytest.raises(TypeError):
        from_roman(bad)


# ---------- strict rejection for from_roman ----------

@pytest.mark.parametrize("s", [
    "", "iv", "Iv", "iV", "X ", " X", "X\n", "X\t", "M CM",
    "IIII", "VV", "LL", "DD", "XXXX", "CCCC",
    "IC", "IL", "IM", "XM", "VM", "IXI", "IVI", "IXX",
    "MMMM", "MMMMM", "MMMMMMMMMM",
    "IIV", "IIX", "VIV", "IXIV", "MCMXCIVX", "XMIX",
    "A", "Z", "0", "?", "-", "M1", "NUL", "MMMMIV",
])
def test_from_roman_rejects_noncanonical_strings(s):
    with pytest.raises(ValueError):
        from_roman(s)


@given(st.sampled_from(["i", "v", "x", "l", "c", "d", "m", " ", "\n", "\t", "a", "0", "Z"]))
def test_from_roman_rejects_lowercase_whitespace_unknown_chars(ch):
    # any single char outside IVXLCDM must be rejected
    assert ch not in _REF_VALUES
    with pytest.raises(ValueError):
        from_roman(ch)


@given(st.integers(min_value=1, max_value=3999))
def test_from_roman_rejects_lowercased_canonical(n):
    s = ref_to_roman(n)
    assert s != s.lower() or True
    with pytest.raises(ValueError):
        from_roman(s.lower())
    # mixed: lowercase only first char must also fail (unless already lowercase, impossible)
    if s[0].isupper():
        with pytest.raises(ValueError):
            from_roman(s[0].lower() + s[1:])


@given(st.integers(min_value=1, max_value=3999))
def test_from_roman_rejects_padded_canonical(n):
    s = ref_to_roman(n)
    with pytest.raises(ValueError):
        from_roman(" " + s)
    with pytest.raises(ValueError):
        from_roman(s + " ")
    with pytest.raises(ValueError):
        from_roman(s + "\n")


@given(st.integers(min_value=1, max_value=3999))
def test_from_roman_rejects_doubled_canonical(n):
    s = ref_to_roman(n)
    doubled = s + s
    # doubled is canonical only if it happens to equal some other canonical numeral;
    # otherwise must raise. Check against reference oracle.
    try:
        expected = ref_from_roman(doubled)
    except ValueError:
        with pytest.raises(ValueError):
            from_roman(doubled)
    else:
        assert from_roman(doubled) == expected


@given(st.text(alphabet="IVXLCDM", min_size=1, max_size=6))
def test_from_roman_agrees_with_reference_on_arbitrary_symbols(s):
    try:
        expected = ref_from_roman(s)
    except ValueError:
        with pytest.raises(ValueError):
            from_roman(s)
    else:
        assert from_roman(s) == expected


def test_from_roman_empty_rejected():
    with pytest.raises(ValueError):
        from_roman("")


def test_from_roman_mmmm_rejected():
    with pytest.raises(ValueError):
        from_roman("MMMM")


def test_to_roman_returns_str_uppercase():
    for n in (1, 2, 3, 4, 5, 40, 90, 400, 900, 3999):
        r = to_roman(n)
        assert type(r) is str
        assert r == r.upper()
        assert len(r) > 0
